<?php

declare(strict_types=1);

namespace Adonyarik\ConsistentApi\Requests;

use Adonyarik\ConsistentApi\Models\ConsistentModel;
use Adonyarik\ConsistentApi\Support\AccessResolver;
use Adonyarik\ConsistentApi\Support\RelationFilter;
use Adonyarik\ConsistentApi\Traits\CanFilter;
use Closure;
use Illuminate\Foundation\Http\FormRequest;
use Illuminate\Validation\Rule;

/**
 * Form request of index actions: pagination, sorting and filtering input.
 *
 * Search{Model}Request classes generated by consistent:create extend it and point $model at the module's
 * model. It validates perpage against config('consistentapi.pagination.per_page'), page, paginate, sort
 * directions and the filter operators enabled in config('consistentapi.filters.operators'); with $model
 * set it also applies the value rules declared on the model's #[Filterable] operators and RelationFilter
 * definitions to the columns the route may use. Which columns exist is decided later by
 * ConsistentController::indexLogic(), which takes the validated input.
 *
 * @package Adonyarik\ConsistentApi\Requests
 * @author Yaroslav Tyrchenko <tyrchenkoy@gmail.com>
 * @since 1.0.0
 */
class BaseSearchRequest extends FormRequest
{
    /**
     * Highest page number a request may ask for.
     *
     * Larger numbers would overflow the offset of the query; a subclass can lower or raise it.
     */
    public const MAX_PAGE = 1_000_000;

    /**
     * Model whose #[Filterable] value rules apply; without it only the base rules do.
     *
     * @var class-string<ConsistentModel>
     */
    protected string $model;

    /**
     * Validation rules of the search input.
     *
     * baseRules() merged with filterValueRules(). A subclass can add rules of its own by overriding it
     * and merging parent::rules().
     *
     * @return array<string, mixed> Laravel validation rules keyed by input path
     *
     * @see BaseSearchRequest::baseRules()
     * @see BaseSearchRequest::filterValueRules()
     */
    public function rules(): array
    {
        return array_merge($this->baseRules(), $this->filterValueRules());
    }

    /**
     * Turns plain lists of filter values into `in` filters before validation.
     *
     * filter[qty][]=1&filter[qty][]=2 means filter[qty][in][]=1&filter[qty][in][]=2. Rewriting it first
     * makes the value rules declared for `in` (['in' => ['array', 'max:2']]) apply to both spellings, so a
     * plain list cannot get around them. A subclass that overrides it must call
     * parent::prepareForValidation().
     */
    protected function prepareForValidation(): void
    {
        $filter = $this->input('filter');

        if (! is_array($filter)) {
            return;
        }

        $rewritten = false;

        foreach ($filter as $column => $value) {
            if (is_array($value) && $value !== [] && array_is_list($value)) {
                $filter[$column] = ['in' => $value];
                $rewritten = true;
            }
        }

        if ($rewritten) {
            $this->merge(['filter' => $filter]);
        }
    }

    /**
     * Rules for perpage, page, paginate, sort and the filter structure.
     *
     * perpage must be one of the values of config('consistentapi.pagination.per_page'), page an integer
     * from 1 to MAX_PAGE (an invalid page is an error, not page 1), paginate true / false / 1 / 0, every
     * sort direction asc or desc (or empty), and every filter value either a scalar or keyed by operators
     * enabled in config('consistentapi.filters.operators').
     *
     * @return array<string, array<int, mixed>> Laravel validation rules keyed by input path
     *
     * @see BaseSearchRequest::allowedOperatorsRule()
     */
    protected function baseRules(): array
    {
        return [
            'perpage' => ['numeric', Rule::in(array_values((array) config('consistentapi.pagination.per_page', [])))],
            'page' => ['nullable', 'integer', 'min:1', 'max:'.static::MAX_PAGE],
            'paginate' => ['nullable', Rule::in(['true', 'false', '0', '1'])],
            'sort' => ['array', 'nullable'],
            'sort.*' => ['string', 'in:asc,desc', 'nullable'],
            'filter' => ['array', 'nullable'],
            'filter.*' => ['nullable', $this->allowedOperatorsRule()],
        ];
    }

    /**
     * Validation rule that rejects filter operators disabled in config.
     *
     * Checks array values only: a list counts as the `in` operator, otherwise the keys are operators. Fails
     * with "The filter operators [...] for "column" are not enabled." Whether the model declares the
     * operator for the column is checked by ConsistentController, not here.
     *
     * @return Closure(string, mixed, Closure): void Closure rule for filter.* and filter.{column}
     */
    protected function allowedOperatorsRule(): Closure
    {
        $allowedOperators = config('consistentapi.filters.operators', []);

        return function (string $attribute, mixed $value, Closure $fail) use ($allowedOperators): void {
            if (! is_array($value)) {
                return;
            }

            // A plain list of values is an `in` filter
            $operators = array_is_list($value) ? ['in'] : array_keys($value);

            $invalid = array_diff($operators, $allowedOperators);

            if (! empty($invalid)) {
                $column = str($attribute)->after('filter.')->toString();

                $fail(sprintf(
                    'The filter operators [%s] for "%s" are not enabled.',
                    implode(', ', $invalid),
                    $column
                ));
            }
        };
    }

    /**
     * Value rules from the model's #[Filterable] operators and relation filters.
     *
     * Skipped when $model is not set or not an existing class. For every column with operators that the
     * route's accesses may use, adds filter.{column} (an array with enabled operators), filter.{column}.*
     * (nullable, so validated() keeps every operator) and filter.{column}.{operator} with the declared
     * rules. A RelationFilter with rules gets them for filter.{column}. Every declared rule list starts
     * with nullable unless it has it already: an empty value means the filter is not set, so
     * ['from' => ['date']] does not reject filter[created_at][from]=. Columns restricted to other accesses
     * get no rules: their values are not validated, and the controller rejects them as unknown columns.
     *
     * @return array<string, array<int, mixed>> Laravel validation rules keyed by input path
     *
     * @see CanFilter::filterRulesMap()
     * @see AccessResolver::forRoute()
     */
    protected function filterValueRules(): array
    {
        if (! isset($this->model) || ! class_exists($this->model)) {
            return [];
        }

        $modelInstance = new $this->model;
        $accesses = app(AccessResolver::class)->forRoute($this->route());

        $rules = [];

        // Columns the route has no access to get no rules: the controller rejects them as unknown
        foreach ($modelInstance->filterRulesMap($accesses) as $column => $operators) {
            if ($operators === null) {
                continue;
            }

            if ($operators instanceof RelationFilter) {
                if ($operators->rules !== []) {
                    $rules["filter.$column"] = [...$this->nullable($operators->rules), $this->allowedOperatorsRule()];
                }

                continue;
            }

            // An explicit key replaces the rules "filter.*" expands to, so the operator check is repeated here
            $rules["filter.$column"] = ['array', 'nullable', $this->allowedOperatorsRule()];
            // validated() drops nested keys without a rule of their own: operators and list items get at least this one
            $rules["filter.$column.*"] = ['nullable'];

            foreach ($operators as $operator => $operatorRules) {
                if (empty($operatorRules)) {
                    continue;
                }

                $rules["filter.$column.$operator"] = $this->nullable($operatorRules);
            }
        }

        return $rules;
    }

    /**
     * Puts nullable first in a list of declared rules, unless it is there already.
     *
     * @param  array<int, mixed>  $rules  Rules declared for a filter value
     *
     * @return array<int, mixed> The rules, starting with nullable
     */
    private function nullable(array $rules): array
    {
        return in_array('nullable', $rules, true) ? array_values($rules) : ['nullable', ...array_values($rules)];
    }
}
